        "target_year": target_year,
        "annual_rate": annual_rate,
        "items": rows,
        "method": "median positive BMW option-list price × compound annual price rate",
        "caveat": "Reference option-price scenario, not a BOM, margin, or supplier-cost forecast.",
    }


